import java.util.ArrayList;
import java.util.List;

interface Rule {
    boolean ok(int x);
}

public class Main {
    static int countIf(List<Integer> box, Rule rule) {
        int n = 0;
        for (int x : box) {
            if (rule.ok(x)) {
                n++;
            }
        }
        return n;
    }

    public static void main(String[] args) {
        List<Integer> box = new ArrayList<>();
        box.add(4);
        box.add(7);
        box.add(2);

        System.out.println(countIf(box, ____));
    }
}

interface Doubler {
    int twice(int x);
}

public class Main {
    public static void main(String[] args) {
        Doubler a = x -> x + 1;
        Doubler b = x -> x * x;
        System.out.println(a.twice(b.twice(3)));
    }
}

